def is_retry(e: EventEnvelope, seen: set[tuple[str, str]]) -> bool:
    key = (e.source, e.id)
    if key in seen:
        return True
    seen.add(key)
    return False

async def on_order(e: EventEnvelope, ack: Ack, nack: Nack) -> None:
    try:
        await process(e)
        await ack()
    except Exception:
        await nack('transient')

def wire(bus: TopicBus) -> None:
    bus.subscribe('orders', 'fulfillment', on_order)

